#!/usr/bin/env node
// PreToolUse: Edit|Write. Blocks hand edits to secrets, lockfiles and generated output.
// Lockfiles change through npm/cargo, generated files through their generator.
// Override: ALLOW_PROTECTED_EDIT=1. Exit 0 = allow, 2 = block. Fails open on its own errors.
"use strict";
const path = require("path");
const PROTECTED = [
  [/(?:^|\/)\.env(?:\.(?!example$)[\w.-]+)?$/i, "it holds secrets"],
  [/(?:^|\/)(?:package-lock\.json|Cargo\.lock)$/i, "lockfiles change through npm/cargo, not by hand"],
  [/(?:^|\/)src-tauri\/(?:gen|target)\//i, "it's generated by the Tauri build"],
  [/(?:^|\/)(?:\.svelte-kit|build|node_modules)\//i, "it's generated or installed output"],
];
try {
  if (process.env.ALLOW_PROTECTED_EDIT === "1") process.exit(0);
  const input = JSON.parse(require("fs").readFileSync(0, "utf8") || "{}");
  const fp = String((input.tool_input && input.tool_input.file_path) || "");
  if (!fp) process.exit(0);
  const root = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  const rel = path.relative(root, path.resolve(root, fp)).split(path.sep).join("/");
  for (const [re, why] of PROTECTED) {
    if (re.test(rel)) {
      console.error(`Blocked: ${rel} is protected because ${why}. If the user wants this edit, restart with ALLOW_PROTECTED_EDIT=1.`);
      process.exit(2);
    }
  }
  process.exit(0);
} catch {
  process.exit(0);
}
